{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Unencrypted HTTP exposed to the internet",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The rule permits unrestricted internet access to TCP port 80, allowing clients to communicate over unencrypted HTTP. Restricting the rule to port 443 prevents cleartext traffic at the network boundary."
    },
    {
      "check_id": "CKV_GCP_104",
      "title": "Firewall rule logging is disabled",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule has no log_config block, reducing visibility into allowed connections from the public internet. Enabling logging supports threat detection and incident investigation."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"http-server\"]\n\n  log_config {\n    metadata = \"INCLUDE_ALL_METADATA\"\n  }\n}\n",
  "fix_summary": "Removed public access to unencrypted TCP port 80 while retaining HTTPS access on port 443. Enabled firewall rule logging with metadata to improve network security monitoring."
}
